<?php
if(!defined('ABSPATH')) { exit; }
final class HPG_Settings {
    public static function save() {
        if(!current_user_can('manage_options')) { wp_die('Administrator access required.'); }check_admin_referer('hpg_settings');
        if(!empty($_POST['reset_defaults'])) { delete_option('hpg_defaults');delete_option('hpg_ui_settings');delete_option('hpg_permissions'); }
        else {
            $size=trim(wp_unslash($_POST['size_mb']??'50'));$timeout=0;$every=absint($_POST['schedule_every']??1);
            $branch=trim(wp_unslash($_POST['branch']??'main'));$schedule=sanitize_key($_POST['schedule']??'off');$unit=sanitize_key($_POST['schedule_unit']??'days');$mode=sanitize_key($_POST['large_mode']??'ask');
            if(!preg_match('~^[A-Za-z0-9][A-Za-z0-9._/-]*$~D',$branch) || strpos($branch,'..')!==false || !in_array($schedule,['off','hpg_15min','hourly','daily','custom'],true) || !in_array($unit,['days','months','years'],true) || !in_array($mode,['ask','skip','upload'],true) || $every<1 || $every>1000 || ($size!=='unlimited' && (!ctype_digit($size) || (float)$size<10 || (float)$size>PHP_INT_MAX/1048576))) { wp_die('Invalid default settings. Check size, branch and schedule.'); }
            $paths=HPG_Engine::normalize_paths(trim(wp_unslash($_POST['paths']??'*')));if(!$paths) { wp_die('Enter default source paths.'); }
            $merge=sanitize_key($_POST['merge_method']??'merge');$height=absint($_POST['preview_height']??70);if(!in_array($merge,['merge','squash','rebase'],true) || $height<30 || $height>90) { wp_die('Invalid merge method or panel height.'); }
            update_option('hpg_defaults',['branch'=>$branch,'paths'=>$paths,'excludes'=>trim(wp_unslash($_POST['excludes']??'')),'include_all'=>!empty($_POST['include_all'])?1:0,'date_branch'=>!empty($_POST['date_branch'])?1:0,'size_mb'=>$size==='unlimited'?0:(int)$size,'timeout_min'=>$timeout,'schedule'=>$schedule,'schedule_every'=>$every,'schedule_unit'=>$unit,'large_mode'=>$mode],false);
            $roles=array_keys(wp_roles()->roles);$roles[]='authenticated';
            $push=sanitize_key($_POST['push_role']??'administrator');$merge_role=sanitize_key($_POST['merge_role']??'administrator');
            if(!in_array($push,$roles,true) || !in_array($merge_role,$roles,true)) { wp_die('Invalid role choice.'); }
            update_option('hpg_permissions',['push_role'=>$push,'merge_role'=>$merge_role,'delegate_merge'=>!empty($_POST['delegate_merge'])?1:0],false);
            update_option('hpg_ui_settings',['merge_method'=>$merge,'preview_height'=>$height],false);
        }
        wp_safe_redirect(admin_url('admin.php?page=hpg-settings&saved=1'));exit;
    }
    public static function connections() {
        $profiles=get_posts(['post_type'=>HPG_Sync::TYPE,'post_status'=>'private','numberposts'=>-1]);
        ?><section class="hpg-card"><h2>Repository connections</h2><a class="hpg-btn" href="<?php echo esc_url(admin_url('admin.php?page=hpg-profiles&profile=0')); ?>">+ Add 1 profile</a><label>Update a profile</label><select onchange="if(this.value)location.assign(this.value)"><option value="">Choose profile to update repository or credentials</option><?php foreach($profiles as $p): ?><option value="<?php echo esc_url(admin_url('admin.php?page=hpg-profiles&profile='.$p->ID)); ?>"><?php echo esc_html($p->post_title); ?></option><?php endforeach; ?></select><details><summary>Compare profile repositories and credential status</summary><p>Tokens and private keys remain hidden. Public key fingerprints identify SSH keys.</p><div class="hpg-table-wrap"><table class="hpg-table"><thead><tr><th>Profile</th><th>Repository</th><th>Branch</th><th>Token</th><th>SSH public key fingerprint</th></tr></thead><tbody><?php foreach($profiles as $p): $c=HPG_Sync::config($p->ID);$pub=get_post_meta($p->ID,'_hpg_public_key',true);$parts=preg_split('/\s+/',trim((string)$pub));$blob=isset($parts[1])?base64_decode($parts[1],true):false;$fingerprint=$blob!==false?'SHA256:'.rtrim(base64_encode(hash('sha256',$blob,true)),'='):'Not generated'; ?><tr><td><?php echo esc_html($p->post_title); ?></td><td><?php echo esc_html($c['url']); ?></td><td><?php echo esc_html($c['branch']); ?></td><td><?php echo get_post_meta($p->ID,'_hpg_token',true)?'Stored · ********':'Not set'; ?></td><td><?php echo esc_html($fingerprint); ?></td></tr><?php endforeach; ?></tbody></table></div></details></section><?php
    }
    public static function page() {
        if(!current_user_can('manage_options')) { return; }$c=HPG_Sync::config(0);$ui=get_option('hpg_ui_settings',[]);
        ?><div class="wrap hpg"><div class="hpg-head"><div><span class="hpg-kicker">HARSH PATEL / PREFERENCES</span><h1>Settings.</h1><p>Set defaults, access permissions and merge options.</p></div></div><?php HPG_Pages::navigation();self::connections();if(!empty($_GET['reset_done'])) { echo '<div class="hpg-alert success">Plugin data reset. CSV archives kept.</div>'; } ?><?php if(!empty($_GET['saved'])): ?><div class="hpg-alert success">Settings updated.</div><?php endif; ?><section class="hpg-card"><h2>Defaults for new profiles</h2><form method="post" action="<?php echo esc_url(admin_url('admin-post.php')); ?>"><?php wp_nonce_field('hpg_settings'); ?><input type="hidden" name="action" value="hpg_settings">
        <?php foreach(['branch'=>'Target branch','paths'=>'Source paths (* means all)','excludes'=>'Exclusions · one per line'] as $key=>$label): ?><label><?php echo esc_html($label); ?></label><textarea name="<?php echo esc_attr($key); ?>" rows="<?php echo $key==='branch'?1:3; ?>"><?php echo esc_textarea($key==='paths' && $c[$key]==='.'?'*':$c[$key]); ?></textarea><?php endforeach; ?>
        <label class="hpg-check"><input type="checkbox" name="include_all" value="1" <?php checked(!empty($c['include_all'])); ?>> Include configuration, media and credential files</label><label class="hpg-check"><input type="checkbox" name="date_branch" value="1" <?php checked(!empty($c['date_branch'])); ?>> Current-date upload branch</label>
        <label>File size · MiB (minimum 10) or unlimited</label><input name="size_mb" value="<?php echo esc_attr($c['size_mb']===0?'unlimited':$c['size_mb']); ?>">
        <?php foreach(['large_mode'=>['ask'=>'Ask before uploading larger files','skip'=>'Skip larger files','upload'=>'Upload reviewed larger files'],'schedule'=>['off'=>'Manual only','hpg_15min'=>'Every 15 minutes','hourly'=>'Every hour','daily'=>'Every day','custom'=>'Custom']] as $key=>$options): ?><label><?php echo esc_html($key==='schedule'?'Automatic upload':'Larger files'); ?></label><select name="<?php echo esc_attr($key); ?>" <?php if($key==='schedule'): ?>onchange="document.getElementById('hpg-default-custom-schedule').hidden=this.value!=='custom';"<?php endif; ?>><?php foreach($options as $value=>$label): ?><option value="<?php echo esc_attr($value); ?>" <?php selected($c[$key],$value); ?>><?php echo esc_html($label); ?></option><?php endforeach; ?></select><?php endforeach; ?><div id="hpg-default-custom-schedule" <?php echo $c['schedule']!=='custom'?'hidden':''; ?>><label>Upload every · 1–1000</label><input type="number" name="schedule_every" min="1" max="1000" value="<?php echo esc_attr($c['schedule_every']); ?>"><label>Days, months or years</label><select name="schedule_unit"><?php foreach(['days'=>'Days','months'=>'Months','years'=>'Years'] as $value=>$label): ?><option value="<?php echo esc_attr($value); ?>" <?php selected($c['schedule_unit'],$value); ?>><?php echo esc_html($label); ?></option><?php endforeach; ?></select></div>

        <h2>Access permissions</h2><?php $permissions=get_option('hpg_permissions',[]);$roles=wp_roles()->roles;foreach(['push_role'=>'Who can push code','merge_role'=>'Who can merge code'] as $key=>$label): ?><label><?php echo esc_html($label); ?></label><select name="<?php echo esc_attr($key); ?>"><?php foreach($roles as $role=>$details): ?><option value="<?php echo esc_attr($role); ?>" <?php selected($permissions[$key]??'administrator',$role); ?>><?php echo esc_html($details['name'].' + administrators'); ?></option><?php endforeach; ?><option value="authenticated" <?php selected($permissions[$key]??'administrator','authenticated'); ?>>All signed-in users + administrators</option></select><?php endforeach; ?><label class="hpg-check"><input type="checkbox" name="delegate_merge" value="1" <?php checked(!empty($permissions['delegate_merge'])); ?>> Enable merge buttons for the selected non-admin role</label><a class="hpg-btn secondary" href="<?php echo esc_url(admin_url('admin.php?page=hpg-git')); ?>">Open branch-to-branch merge page</a>
<h2>Preview and merge options</h2><label>Preview panel maximum height · vh (30–90)</label><input type="number" name="preview_height" min="30" max="90" value="<?php echo esc_attr($ui['preview_height']??70); ?>"><label>Accept code · GitHub merge method</label><select name="merge_method"><?php foreach(['merge'=>'Merge commit','squash'=>'Squash merge','rebase'=>'Rebase merge'] as $value=>$label): ?><option value="<?php echo esc_attr($value); ?>" <?php selected($ui['merge_method']??'merge',$value); ?>><?php echo esc_html($label); ?></option><?php endforeach; ?></select><p class="hpg-help">Merges update GitHub only.</p><div class="hpg-row"><button class="hpg-btn">Save settings</button><button class="hpg-btn secondary" name="reset_defaults" value="1" formnovalidate onclick="return confirm('Reset new-profile defaults and shared UI settings? Existing profiles stay intact.');">Reset defaults</button><a class="hpg-btn secondary" href="<?php echo esc_url(admin_url('admin.php?page=hpg-history')); ?>">History settings</a><a class="hpg-btn secondary" href="<?php echo esc_url(admin_url('admin.php?page=hpg-profiles')); ?>">Profiles and Git tools</a></div></form></section><?php HPG_Maintenance::panel(); ?></div><?php
    }
}
